    67	func TestWriterEscapesControlSequences(t *testing.T) {
    68		t.Parallel()
    69		for _, testCase := range escapeCases {
    70			t.Run(testCase.name, func(t *testing.T) {
    71				t.Parallel()
    72				var buffer bytes.Buffer
    73				written, err := NewWriter(&buffer).Write([]byte(testCase.in))
    74				if err != nil {
    75					t.Fatal(err)
    76				}
    77				// The count describes the caller's buffer, not the sink's, so a
    78				// renderer that checks it against len(p) never sees a short write.
    79				if written != len(testCase.in) {
    80					t.Errorf("Write reported %d bytes, want %d", written, len(testCase.in))
    81				}
    82				if got := buffer.String(); got != testCase.want {
    83					t.Errorf("Write(%q) wrote %q, want %q", testCase.in, got, testCase.want)
    84				}
    85			})
    86		}
    87	}
